// Fixed-score endpoint-ball bounds; reuses audited exact integer ages/partition.
#include "../expiry_runtime_20261003/kernel.cpp"
struct TubeContext:Context {double epsilon=0;using Context::Context;};
bool clipped_interval(V o,V d,V extent,double oz,double dz,double cut,double& leave){double lo=0,hi=std::numeric_limits<double>::infinity();for(int i=0;i<3;i++){if(std::abs(d[i])<=1e-12){if(std::abs(o[i])>extent[i])return false;}else{double a=(-extent[i]-o[i])/d[i],b=(extent[i]-o[i])/d[i];lo=std::max(lo,std::min(a,b));hi=std::min(hi,std::max(a,b));}}if(dz>1e-12)lo=std::max(lo,(cut-oz)/dz);else if(dz< -1e-12)hi=std::min(hi,(cut-oz)/dz);else if(oz<cut)return false;leave=hi;return hi>=lo&&lo<=1+1e-10;}
std::array<Counts,2> unknown_counts(const Rays& rays){std::array<Counts,2> c{};for(auto& r:rays.rays){c[1].n++;c[1].h++;if(r.stride==16){c[0].n++;c[0].h++;}}return c;}
std::array<Counts,2> tube_count(const Boxes& original,const Rays& rays,double eps){if(eps==0)return count(original,rays);std::array<Counts,2> out{};if(!original.resolved)return unknown_counts(rays);Boxes b=original;double delta=eps*(1+2e-10)+1e-9;bool inside=true;for(int i=0;i<3;i++){b.inner[i]-=delta;b.outer[i]+=delta;if(b.inner[i]<=0)return unknown_counts(rays);if(std::abs(b.o[i])>b.outer[i])inside=false;}if(inside)return unknown_counts(rays);M rt=trans(b.r);
 auto f=[&](const Ray& ray){V d=mv(rt,ray.d);double leave=0,dummy=0;bool possible=clipped_interval(b.o,d,b.outer,rays.origin[2],ray.d[2],.15-delta,leave);bool definite=clipped_interval(b.o,d,b.inner,rays.origin[2],ray.d[2],.15+delta,dummy);Counts cc{possible,definite,definite&&leave<1-1e-10,possible&&leave>=1-1e-10};out[1]=plus(out[1],cc);if(ray.stride==16)out[0]=plus(out[0],cc);};V v=sub(b.center,rays.origin);double distance=norm(v),radius=norm(b.outer)+1e-7;if(distance<=radius){for(auto& rr:rays.rays)f(rr);}else{for(double& x:v)x/=distance;double cosine=sqrt(std::max(0.,1-(radius/distance)*(radius/distance))),chord=sqrt(std::max(0.,2*(1-cosine)))+1e-10;rays.query(rays.root,v,chord*chord,f);}return out;
}

extern "C" {
void* tube_build(const double* e,const double* a,const double* road,const double* origin,double qx,double qy,int64_t radius,int64_t qn,int64_t qd,const double* points,const int* stride,int nrays,int budget,double epsilon){try{if(!std::isfinite(epsilon)||epsilon<0||epsilon>.1||budget<1||budget>1000000||radius<0||radius>10000000||qn<0||qd<=0||qn>qd||nrays<0)return nullptr;auto begin=std::chrono::steady_clock::now();TubeContext* c=new TubeContext(e,a,road,origin,qx,qy,radius,qn,qd);c->epsilon=epsilon;Rays rays(points,stride,nrays,c->origin);Node root{};double pi=M_PI;double lo[6]={-12,-8,e[2]-.1,-pi/90,0,-pi/90},hi[6]={12,8,e[2]+.1,pi/90,2*pi,pi/90};std::copy(lo,lo+6,root.lo);std::copy(hi,hi+6,root.hi);root.lower=lower(root,qx,qy,radius);c->nodes.reserve(2*budget+1);c->nodes.push_back(root);using Q=std::pair<int,int>;std::priority_queue<Q,std::vector<Q>,std::greater<Q>> queue;queue.push({root.lower,0});c->counts.resize(1);c->geometries.resize(1);V padded=c->extent;for(double& x:padded)x+=.03;double body=norm(padded);
 while(!queue.empty()&&c->inspected<budget){int i=queue.top().second;queue.pop();c->inspected++;Node& n=c->nodes[i];if(n.lower>=c->outside_upper-1){n.status=3;continue;}Boxes b=boxes(n,c->extent,c->anchor,c->road,c->origin);auto cc=tube_count(b,rays,epsilon);c->counts[i]=cc;c->geometries[i]=b;if(excludes(cc[0],qn,qd)||excludes(cc[1],qn,qd)){n.status=2;continue;}if(c->inspected==budget){n.status=4;break;}int axis=0;double weight=-1;for(int j=0;j<6;j++){double h=(n.hi[j]-n.lo[j])/2;double w=j<3?h:2*body*sin(std::min(h,pi)/2);if(w>weight){weight=w;axis=j;}}double mid=(n.lo[axis]+n.hi[axis])/2;Node left=n,right=n;left.hi[axis]=mid;right.lo[axis]=mid;left.parent=right.parent=i;left.status=right.status=0;left.lower=lower(left,qx,qy,radius);right.lower=lower(right,qx,qy,radius);n.status=1;n.left=c->nodes.size();n.right=n.left+1;int j=n.left;c->nodes.push_back(left);c->nodes.push_back(right);c->counts.resize(c->nodes.size());c->geometries.resize(c->nodes.size());queue.push({left.lower,j});queue.push({right.lower,j+1});}
 c->elapsed=std::chrono::duration<double>(std::chrono::steady_clock::now()-begin).count();return static_cast<Context*>(c);}catch(...){return nullptr;}}
void tube_destroy(void* ptr){delete static_cast<TubeContext*>(static_cast<Context*>(ptr));}
// mode1: cached ball counts - exception-old-ball + exception-current-exact.
// mode0: recompute all inlier-ball and exception-exact counts from scratch.
void tube_revalidate(void* ptr,const double* inpoints,const int* instride,int inn,const double* oldp,const int* olds,int oldn,const double* newp,const int* news,int newn,int mode,int64_t* output,int* accepted,double* stat){auto begin=std::chrono::steady_clock::now();auto c=static_cast<TubeContext*>(static_cast<Context*>(ptr));Rays inliers(inpoints,instride,inn,c->origin),oldr(oldp,olds,oldn,c->origin),newr(newp,news,newn,c->origin);int lower_us=c->outside_lower,excluded=0,revoked=0;
 for(size_t i=0;i<c->nodes.size();i++){const Node& n=c->nodes[i];if(n.status==1){accepted[i]=-1;continue;}std::array<Counts,2> cc{};bool rejected=false;if(n.status==2){auto exact=count(c->geometries[i],newr);if(mode){auto removed=tube_count(c->geometries[i],oldr,c->epsilon);for(int s=0;s<2;s++)cc[s]=plus(plus(c->counts[i][s],removed[s],-1),exact[s]);}else{auto rest=tube_count(c->geometries[i],inliers,c->epsilon);for(int s=0;s<2;s++)cc[s]=plus(rest[s],exact[s]);}rejected=excludes(cc[0],c->qn,c->qd)||excludes(cc[1],c->qn,c->qd);revoked+=!rejected;}accepted[i]=rejected?1:0;if(rejected)excluded++;else lower_us=std::min(lower_us,n.lower);for(int s=0;s<2;s++){int64_t v[4]={cc[s].n,cc[s].m,cc[s].k,cc[s].h};std::copy(v,v+4,output+8*i+4*s);}}
 stat[0]=lower_us;stat[1]=c->outside_upper;stat[2]=std::chrono::duration<double>(std::chrono::steady_clock::now()-begin).count();stat[3]=excluded;stat[4]=revoked;
}
// Test-only export of interval counts for arbitrary continuous boxes.
void tube_test_counts(const double* points,const int* stride,int n,const double* origin,const double* center,const double* rotation,const double* inner,const double* outer,double epsilon,int64_t* output){Boxes b{};std::copy(center,center+3,b.center.begin());std::copy(rotation,rotation+9,b.r.begin());std::copy(inner,inner+3,b.inner.begin());std::copy(outer,outer+3,b.outer.begin());V o{origin[0],origin[1],origin[2]};b.o=mv(trans(b.r),sub(o,b.center));b.resolved=true;bool inside=true;for(int i=0;i<3;i++){if(inner[i]<=0)b.resolved=false;if(std::abs(b.o[i])>outer[i])inside=false;}b.resolved&=!inside;Rays rays(points,stride,n,o);auto cc=tube_count(b,rays,epsilon);for(int s=0;s<2;s++){int64_t v[4]={cc[s].n,cc[s].m,cc[s].k,cc[s].h};std::copy(v,v+4,output+4*s);}}
}
